[Fact]
public void ABackslashInTextAPlayerReadsIsAnError()
{
    var world = World.FromJson("""
    {
      "spawnLocation": 1,
      "locations": [
        {
          "index": 1, "name": "A", "isExit": true,
          "interactions": [
            {
              "triggers": ["*knock*"],
              "actions": [ { "action": "describe", "parameters": ["Nobody answers.\\nYou wait."] } ]
            }
          ]
        }
      ]
    }
    """);

    var issues = WorldValidator.Validate(world);
    Assert.Contains(issues, issue =>
        issue.Severity == ValidationIssue.Error && issue.Message.Contains("backslash"));
}

[Fact]
public void ARealLineBreakIsNotAnError()
{
    var world = World.FromJson("""
    {
      "spawnLocation": 1,
      "locations": [
        {
          "index": 1, "name": "A", "isExit": true,
          "interactions": [
            {
              "triggers": ["*knock*"],
              "actions": [ { "action": "describe", "parameters": ["Nobody answers.\nYou wait."] } ]
            }
          ]
        }
